save(51,dict(paragraphs=['Jyoti Jha writes fiction, poetry and travel narratives in English and Hindi. A former human-resources professional, she found a turning point in The Times of India’s Write India competition, later discussing that journey at Times LitFest. Her books include the Hindi novel Aanandi, the travel title Around the World Through My Lens and the short-story collection Heart’s Sanctuary & Other Stories.','“Hues of Nature” gathers its movement from colour and light: blue sky, green foliage, grey shadow and golden rays. The quiet scene opens into a reflection on solitude and purpose, letting sensory attention become a way of looking inward. Her author website also records the poem’s appearance in the Toshali Anthology of Poetry, connecting this Kabita Live contribution with her wider poetry publication.'],sources=[source('Jyoti Jha — author website','https://myviewsandreviews.in/about-me/',['Former HR profession, English/Hindi books, Aanandi, travel writing and Hues of Nature in Toshali Anthology of Poetry.']),source('Times of India — Jyoti Jha at Times LitFest','https://timesofindia.indiatimes.com/life-style/books/features/i-bifurcate-my-life-before-and-after-write-india-author-jyoti-jha-at-times-litfest-delhi/articleshow/98510723.cms',['Write India winner and 2023 From Write India to Published Author panel; reported career transition.']),source('Google Books — Heart’s Sanctuary & Other Stories','https://books.google.com/books/about/HEART_S_SANCTUARY_Other_Stories.html?id=f_d4EAAAQBAJ',['Jyoti Jha, Booksclinic Publishing, 2022 fiction volume.'])],books=[dict(title='Heart’s Sanctuary & Other Stories',detail='Short stories · Booksclinic Publishing, 2022',url='https://books.google.com/books/about/HEART_S_SANCTUARY_Other_Stories.html?id=f_d4EAAAQBAJ')],identity_match='HR-to-author history, Write India recognition, named books and exact poem title Hues of Nature on author website match captured writer. Unrelated engineering researcher with same name excluded.',poems_read=[dict(id=74,title='Hues of Nature',basis='Full English original, twelve lines, read: colours, foliage, breeze, light, solitude and inward purpose.')],limitations=['Award inventories, honorary titles, current organization posts and sales superlatives omitted.','Toshali appearance is author-reported, explicitly attributed in narrative.','No autobiographical conclusion inferred from poetic solitude.'],research_leads=[dict(url='https://orcid.org/0000-0003-3967-1541',finding='Materials/engineering researcher namesake; no identity bridge, excluded.')],next_action='Independent author/editor review of concise biography and literary reading.'))
